#!/usr/bin/env python3
"""Patch the Android project generated by `flutter create` for StreamMKV.

Run from app/ after:
    flutter create --org dev.un4ckn0wl3z --project-name streammkv --platforms android .
"""
import pathlib
import re
import sys

root = pathlib.Path(__file__).resolve().parent.parent
manifest = root / "android/app/src/main/AndroidManifest.xml"
if not manifest.exists():
    sys.exit(f"{manifest} not found — run `flutter create --platforms android .` first")

m = manifest.read_text()

# Network access (release manifests don't get INTERNET by default) and plain-HTTP seedboxes.
if "android.permission.INTERNET" not in m:
    m = re.sub(r"(<manifest[^>]*>)", r'\1\n    <uses-permission android:name="android.permission.INTERNET"/>', m, count=1)
if "usesCleartextTraffic" not in m:
    m = m.replace("<application", '<application\n        android:usesCleartextTraffic="true"', 1)
m = re.sub(r'android:label="[^"]*"', 'android:label="StreamMKV"', m, count=1)
# url_launcher: allow resolving browsers for https links (Android 11+ package visibility)
if 'android.intent.action.VIEW' not in m:
    m = m.replace("</manifest>", """    <queries>
        <intent>
            <action android:name="android.intent.action.VIEW"/>
            <data android:scheme="https"/>
        </intent>
    </queries>
</manifest>""", 1)

# audio_service: background music (foreground service + media notification / lock screen)
if 'xmlns:tools' not in m:
    m = m.replace('<manifest xmlns:android="http://schemas.android.com/apk/res/android"',
                  '<manifest xmlns:android="http://schemas.android.com/apk/res/android"\n    xmlns:tools="http://schemas.android.com/tools"', 1)
for perm in ("WAKE_LOCK", "FOREGROUND_SERVICE", "FOREGROUND_SERVICE_MEDIA_PLAYBACK"):
    if f"android.permission.{perm}\"" not in m:
        m = re.sub(r"(<manifest[^>]*>)", rf'\1\n    <uses-permission android:name="android.permission.{perm}"/>', m, count=1)
if "com.ryanheise.audioservice.AudioService" not in m:
    m = m.replace("</application>", """        <service android:name="com.ryanheise.audioservice.AudioService"
            android:foregroundServiceType="mediaPlayback"
            android:exported="true" tools:ignore="Instantiatable">
            <intent-filter>
                <action android:name="android.media.browse.MediaBrowserService"/>
            </intent-filter>
        </service>
        <receiver android:name="com.ryanheise.audioservice.MediaButtonReceiver"
            android:exported="true" tools:ignore="Instantiatable">
            <intent-filter>
                <action android:name="android.intent.action.MEDIA_BUTTON"/>
            </intent-filter>
        </receiver>
    </application>""", 1)

# offline library: background downloads (background_downloader) and the user's own video folders
for perm in ("POST_NOTIFICATIONS", "FOREGROUND_SERVICE_DATA_SYNC", "RUN_USER_INITIATED_JOBS", "READ_MEDIA_VIDEO"):
    if f"android.permission.{perm}\"" not in m:
        m = re.sub(r"(<manifest[^>]*>)", rf'\1\n    <uses-permission android:name="android.permission.{perm}"/>', m, count=1)
if "android.permission.READ_EXTERNAL_STORAGE" not in m:
    m = re.sub(r"(<manifest[^>]*>)", r'\1\n    <uses-permission android:name="android.permission.READ_EXTERNAL_STORAGE" android:maxSdkVersion="32"/>', m, count=1)
if "SystemForegroundService" not in m:
    m = m.replace("</application>", """        <service android:name="androidx.work.impl.foreground.SystemForegroundService"
            android:foregroundServiceType="dataSync" tools:node="merge"/>
    </application>""", 1)

manifest.write_text(m)
print("patched", manifest)

# audio_service needs its activity subclass to hand media sessions to the engine
for act in root.glob("android/app/src/main/**/MainActivity.kt"):
    k = act.read_text()
    if "AudioServiceActivity" not in k:
        k = k.replace("import io.flutter.embedding.android.FlutterActivity", "import com.ryanheise.audioservice.AudioServiceActivity")
        k = re.sub(r":\s*FlutterActivity\(\)", ": AudioServiceActivity()", k)
        act.write_text(k)
        print("patched", act)

# Release builds shrink resources, and audio_service looks its notification / lock-screen
# button icons up by name — so they were stripped and every media-session update failed
# ("You must specify an icon resource id to build a CustomAction"): no notification, no
# lock-screen controls. Keep them (and the notification icon).
keep = root / "android/app/src/main/res/raw/keep.xml"
keep.parent.mkdir(parents=True, exist_ok=True)
keep.write_text("""<?xml version="1.0" encoding="utf-8"?>
<resources xmlns:tools="http://schemas.android.com/tools"
    tools:keep="@drawable/audio_service_*,@mipmap/ic_launcher,@drawable/ic_launcher*" />
""")
print("wrote", keep)

# flutter create adds a counter-app widget test that doesn't match this app
test = root / "test/widget_test.dart"
if test.exists():
    test.unlink()
